function readDataConsent(){try{const value=JSON.parse(localStorage.getItem(DATA_CONSENT_KEY)||'null');return value&&value.version===DATA_CONSENT_VERSION&&['accepted','declined','withdrawn'].includes(value.status)?value:{status:'unknown',version:DATA_CONSENT_VERSION}}catch{return {status:'unknown',version:DATA_CONSENT_VERSION}}}
let dataConsent=readDataConsent();
window.hasDataProcessingConsent=()=>dataConsent.status==='accepted'&&dataConsent.version===DATA_CONSENT_VERSION;
function recordDataConsent(status){dataConsent={status,version:DATA_CONSENT_VERSION,recorded_at:new Date().toISOString()};try{localStorage.setItem(DATA_CONSENT_KEY,JSON.stringify(dataConsent))}catch{toast('本机无法保存授权选择，下次可能需要重新确认')}}
const providerLinks=()=>`<div class="consent-links"><a href="https://terms.alicdn.com/legal-agreement/terms/common_product_agreement/20260423150805928/20260423150805928.html" target="_blank" rel="noopener">千问隐私政策</a><a href="https://terms.alicdn.com/legal-agreement/terms/common_platform_service/20260423145804812/20260423145804812.html" target="_blank" rel="noopener">千问服务协议</a><a href="https://docs.volcengine.com/docs/ark/volcengine-ark-platform-terms?lang=zh" target="_blank" rel="noopener">火山方舟服务条款</a><a href="https://docs.volcengine.com/docs/Legalagreements/VolcanoEnginesPrivacyPolicy?lang=zh" target="_blank" rel="noopener">火山引擎隐私政策</a></div>`;
