function renderPractice(){const recent=state.previewRecent==='empty'?[]:rehearsals.filter(p=>p.status==='completed').slice(0,5);const scenarios=[['interview','user','电话面试'],['inquiry','records','咨询了解'],['apology','speaking','道歉解释'],['bargaining','retry','价格谈判'],['refusal','phone','礼貌拒绝'],['complaint','records','投诉维权'],['followup','retry','催办跟进'],['custom','edit','自定义']];return `<div class="app-body practice-home"><div class="practice-home-intro"><h1>今天想练什么？</h1><p class="practice-scene-subtitle">选择一个场景，练好再开口</p>${moduleButton('scenarioSelection')}</div><div class="practice-scene-tiles">${scenarios.map(([id,glyph,label])=>`<button type="button" class="practice-scene-tile scene-${id}" data-scenario="${id}"><span class="scene-tile-icon">${icon(glyph)}</span><strong>${label}</strong>${icon('arrow')}</button>`).join('')}</div><div class="section-heading practice-recent-heading"><h3>最近演练</h3><div class="section-heading-actions">${recent.length?goto('查看全部','practice-records','ghost-button'):''}${moduleButton('practiceRecent')}</div></div><div class="practice-recent-list">${recent.map(p=>`<button class="practice-recent-item" type="button" data-practice="${p.id}"><span><time>${esc(p.date)}</time><small>我扮演：${esc(p.goal.userRole)}</small><small>AI 扮演：${esc(p.goal.role)}</small></span>${icon('arrow')}</button>`).join('')||'<div class="recent-empty"><span aria-hidden="true">'+icon('speaking')+'</span><strong>暂无演练记录</strong><p>选择上方场景，开始第一次演练吧。</p></div>'}</div></div>${tabs('practice')}`}

function inputCount(id,value,max){return `<small class="input-count ${countInputText(value)>max?'over-limit':''}" id="${id}-count" aria-live="polite">${countInputText(value)} / ${max}</small>`}
function updateInputCount(input){const max=Number(input.dataset.textLimit);if(!max)return;const count=countInputText(input.value);input.setAttribute('aria-invalid',String(count>max));input.setCustomValidity(count>max?`最多${max}字，当前${count}字`: '');const counter=$('#'+input.id+'-count');if(counter){counter.textContent=`${count} / ${max}`;counter.classList.toggle('over-limit',count>max)}}
function field(label,key,type='textarea'){const rule=INPUT_RULES.goal[key];const placeholder={userRole:'例如：求职者',role:'例如：面试官',objective:'用一句话简单描述'}[key]||'';const specKey={userRole:'practiceUserRole',role:'practiceAiRole',objective:'practiceObjective',background:'practiceBackground',notes:'practiceNotes'}[key];return `<div class="field-heading"><label class="field-label" for="goal-${key}">${label}</label>${specKey?moduleButton(specKey):''}</div>${type==='textarea'?`<textarea id="goal-${key}" class="input-field" rows="${key==='objective'?3:2}" data-goal-field="${key}" data-text-limit="${rule.max}" aria-describedby="goal-${key}-count" placeholder="${esc(placeholder)}">${esc(state.goal[key])}</textarea>`:`<input id="goal-${key}" class="input-field" data-goal-field="${key}" data-text-limit="${rule.max}" aria-describedby="goal-${key}-count" placeholder="${esc(placeholder)}" value="${esc(state.goal[key])}">`}${inputCount('goal-'+key,state.goal[key],rule.max)}`}
function goalCanSubmit(){return Object.hasOwn(SCENARIOS,state.goal.scenario)&&!validateInputFields('goal',state.goal)}
function syncGoalSubmitButtons(){const invalid=!goalCanSubmit();for(const selector of ['[data-action="prepare-goal"]','[data-action="begin-session"]']){const button=$(selector);if(button)button.disabled=invalid}}
function renderGoal(){return `<div class="confirmation-page preparation-page">${header('设定目标','practice')}<div class="app-body confirmation-scroll"><section class="card"><h3 class="preparation-card-title">本次演练</h3>${`<div class="field-heading"><label class="field-label" for="scenario">场景</label>${moduleButton('scenarioSelection')}</div><input id="scenario" class="input-field" value="${esc(SCENARIOS[state.goal.scenario]?.label||'')}" readonly aria-readonly="true"><div class="goal-role-pair"><div>${field('我扮演 *','userRole','input')}</div><div>${field('AI 扮演 *','role','input')}</div></div>${field('对话目的 *','objective')}${field('背景','background')}${field('备注','notes')}`}</section>${state.goalError?`<p class="form-error" role="alert">${esc(state.goalError)}</p>`:''}</div><footer class="confirmation-footer">${region('practiceStart',action('开始','prepare-goal','primary-button',goalCanSubmit()?'':'disabled'),'button-spec-region practice-start-region')}</footer></div>`}
function renderGoalConfirm(){return `<div class="confirmation-page">${header('确认目标','goal')}<div class="app-body confirmation-scroll"><div class="page-intro"><p>核对双方角色和目标，确认后开始对话。</p></div>${card('goalConfirmation',sc(state.goal).label,goalLines(state.goal))}${region('microphoneNotice','<div class="light-note">开始后将申请麦克风权限，请允许使用，否则将无法正常开始对话。</div>')}</div><footer class="confirmation-footer">${region('practiceConnectionStart',action('确认并开始对练','begin-session','primary-button',goalCanSubmit()?'':'disabled'),'button-spec-region')}${goto('返回修改','goal','ghost-button full-width')}</footer></div>`}
function sessionDuration(){const seconds=Math.max(0,Math.floor(state.sessionElapsedSeconds));return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`}
function renderSession(){
  if(!STORE_SHOT&&(state.sessionStatus==='exhausted'||practiceRemaining()<=0))return `${header('沟通中','practice')}<div class="app-body"><div class="empty-state"><h1>今日演练已结束</h1><p>${PRACTICE_LIMIT_MESSAGE}</p><p>已自动断开，已有对话已保留。北京时间明日零点重置额度。</p>${goto('查看复盘','records')}</div></div>`;
  const g=state.confirmedGoal||state.goal;
  const status=state.sessionMode==='example'?'正在听你说':state.sessionStatus==='error'?'连接遇到问题':({connecting:'正在连接',listening:'正在听你说',recognizing:'正在识别',responding:'对方正在说话'}[state.sessionStatus]||'准备中');
  const unavailable=['connecting','error'].includes(state.sessionStatus);
  return `<div class="practice-call-page ${state.sessionTranscriptOpen?'transcript-open':''}"><div class="practice-call-heading">${moduleButton('realtimePractice')}</div><div class="practice-call-identity"><span class="practice-call-avatar">${icon('user')}</span><div class="practice-call-status" role="status">${status}</div><time id="practice-call-duration" class="practice-call-duration" aria-label="本次演练时长">${sessionDuration()}</time></div><div class="practice-call-content" data-region="practiceTranscript"><section id="practice-transcript" class="practice-transcript" aria-label="演练对话" ${state.sessionTranscriptOpen?'':'hidden'}><div class="practice-transcript-header"><strong>对话记录</strong><button type="button" class="ghost-button" data-action="toggle-session-transcript" aria-label="收起对话记录">收起⌄</button></div><div class="chat-log" tabindex="0" aria-label="对话内容" aria-live="polite">${state.sessionTurns.map(t=>`<div class="chat-bubble ${t.speaker==='user'?'user':'ai'}"><span>${t.speaker==='user'?`我（${esc(g.userRole)}）`:`AI（${esc(g.role)}）`}</span><p>${esc(t.text)}</p></div>`).join('')||'<p class="empty-caption">对话开始后，文字记录将在这里显示。</p>'}</div></section>${state.sessionStatus==='error'?`<p class="form-error" role="alert">${esc(state.sessionError)}</p>`:''}</div><div class="practice-call-bottom">${state.sessionStatus==='error'?action('重新连接','recover-session','secondary-button full-width'):''}<div class="practice-transcript-action spec-region"><button type="button" class="practice-transcript-toggle" data-action="toggle-session-transcript" aria-expanded="${state.sessionTranscriptOpen}" aria-controls="practice-transcript">${icon('records')}<span>对话记录</span></button>${moduleButton('practiceTranscript')}</div><p class="practice-call-hint">${state.sessionMode==='example'?'':unavailable?'连接成功后，直接开口说话':'直接开口，像打电话一样沟通'}</p><div class="practice-call-controls">${action(`<span>${icon('phone')}</span><small>结束对话</small>`,'finish-session','practice-call-control practice-call-end')}</div></div></div>`;
}
